/*
 * A136443  Numbers m such that A102863(m) = 1.
 * https://oeis.org/A136443
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth positive integer m such that the sum of the first
 *            m primes is composite (m = 1 is included by definition). The
 *            sequence is generated by scanning the primes one by one,
 *            accumulating the sum, and adding the index whenever the sum is
 *            composite (or when the index is 1). The implementat...
 * Range:     u8 n <= 9, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   isPrimeTrial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include "../utils/isPrimeTrial.h"

seq_t a(idx_t n) {
    /* --------------- static state ---------------- */
    static bool initialized = false;
    static seq_t *results = NULL;
    static size_t res_len  = 0, res_cap = 0;
    static uint64_t *primes = NULL;
    static size_t  pr_len = 0, pr_cap = 0;
    static idx_t  candidate = 2;      /* next candidate to test for primality   */
    static idx_t  current_m = 0;      /* number of primes processed so far      */
    static seq_t  sum = 0;            /* sum of the first current_m primes      */

    /* --------------- initialization ---------------- */
    if (!initialized) {
        res_cap = 16;
        results = (seq_t*)malloc(res_cap * sizeof(seq_t));
        pr_cap  = 16;
        primes  = (uint64_t*)malloc(pr_cap * sizeof(uint64_t));
        initialized = true;
    }

    /* --------------- extend sequence if needed --- */
    while (res_len < n) {
        /* --- find the next prime (trial division) --- */
        while (true) {
            bool is_prime = true;
            for (size_t i = 0; i < pr_len; ++i) {
                uint64_t p = primes[i];
                if (p * p > candidate) break;
                if (candidate % p == 0) {
                    is_prime = false;
                    break;
                }
            }
            if (is_prime) break;
            candidate += (candidate == 2 ? 1 : 2);  /* skip even numbers after 2 */
        }

        /* --- store the new prime --- */
        if (pr_len == pr_cap) {
            pr_cap = pr_cap * 2;
            primes = (uint64_t*)realloc(primes, pr_cap * sizeof(uint64_t));
        }
        primes[pr_len++] = candidate;

        /* --- update running sum and index --- */
        sum += (seq_t)candidate;
        ++current_m;   /* now current_m == index m of the cumulative sum */

        /* --- decide if current_m should be added to results --- */
        bool include = false;
        if (current_m == 1)
            include = true;   /* m = 1 is always included */
        else
            include = !isPrimeTrial(sum);

        if (include) {
            if (res_len == res_cap) {
                res_cap = res_cap * 2;
                results = (seq_t*)realloc(results, res_cap * sizeof(seq_t));
            }
            results[res_len++] = (seq_t)current_m;
        }

        /* --- prepare next candidate --- */
        candidate += (candidate == 2 ? 1 : 2);
    }

    return results[n - 1];
}
